        full_fwd, anneal_fwd, anneal_len, tm_fwd = primers['fwd']
        print(f"{template_name}_fwd: TM={tm_fwd:.1f}°C, anneal_len={anneal_len}bp")
    else:
        print(f"{template_name}_fwd: DESIGN FAILED")

    if 'rev' in primers:
        full_rev, anneal_rev, anneal_len, tm_rev = primers['rev']
        print(f"{template_name}_rev: TM={tm_rev:.1f}°C, anneal_len={anneal_len}bp")
    else:
        print(f"{template_name}_rev: DESIGN FAILED")

    if 'fwd' in primers and 'rev' in primers:
        tm_fwd = primers['fwd'][3]
        tm_rev = primers['rev'][3]
        diff = abs(tm_fwd - tm_rev)
        print(f"  TM diff: {diff:.1f}°C {'✓' if diff <= 5 else '✗'}")
    print()

