import subprocess

def get_oligotm(seq):
    result = subprocess.run(
        ['oligotm', '-tp', '1', '-sc', '1', '-mv', '50', '-dv', '2', '-n', '0.8', '-d', '500', seq],
        capture_output=True, text=True
    )
    try:
        return float(result.stdout.strip())
    except:
        return None

def reverse_complement(seq):
    seq = seq.upper()
    comp = {'A': 'T', 'T': 'A', 'G': 'C', 'C': 'G'}
    return ''.join(comp[c] for c in reversed(seq))

def design_primers_optimized(template_name, template_seq):
    bsai_fwd = "GGTCTC"
    bsai_rev = "GAGACC"

    overhangs = {
        'input': ('AAAA', 'TTTT'),
        'egfp': ('GGGG', 'CCCC'),
        'flag': ('CCCC', 'GGGG'),
        'snap': ('TTTT', 'AAAA')
    }

    fwd_oh, rev_oh = overhangs.get(template_name, ('AAAA', 'TTTT'))

    best_pair = None
    best_diff = float('inf')

    for anneal_len_fwd in range(45, 14, -1):
        anneal_fwd = template_seq[:anneal_len_fwd]
        tm_fwd = get_oligotm(anneal_fwd)

        if not tm_fwd or not (58 <= tm_fwd <= 72):
            continue

        template_rc = reverse_complement(template_seq)
        for anneal_len_rev in range(45, 14, -1):
            anneal_rev = template_rc[:anneal_len_rev]
            tm_rev = get_oligotm(anneal_rev)

            if not tm_rev or not (58 <= tm_rev <= 72):
                continue

            diff = abs(tm_fwd - tm_rev)
            if diff <= 5 and diff < best_diff:
                full_fwd = bsai_fwd + fwd_oh + anneal_fwd
                full_rev = bsai_rev + rev_oh + anneal_rev
                best_pair = {
                    'fwd': (full_fwd, tm_fwd),
                    'rev': (full_rev, tm_rev),
                    'diff': diff
                }
                best_diff = diff

    return best_pair

sequences = {}
with open('sequences.fasta', 'r') as f:
    current_header = None
    for line in f:
        line = line.strip()
        if line.startswith('>'):
            current_header = line[1:]
            sequences[current_header] = ''
        else:
            sequences[current_header] += line.upper()

with open('primers.fasta', 'w') as out:
    for template_name in ['input', 'egfp', 'flag', 'snap']:
        template_seq = sequences[template_name]
        primers = design_primers_optimized(template_name, template_seq)

        if primers:
            fwd_seq, tm_fwd = primers['fwd']
            rev_seq, tm_rev = primers['rev']

            out.write(f">{{template_name}}_fwd\n{{fwd_seq}}\n".format(
                template_name=template_name,
                fwd_seq=fwd_seq
            ))
            out.write(f">{{template_name}}_rev\n{{rev_seq}}\n".format(
                template_name=template_name,
                rev_seq=rev_seq
            ))

